//! The clipboard half of pasting on macOS (the general pasteboard).
//!
//! [`Session::begin`] snapshots every item on the pasteboard with every type it has, and
//! [`Session::publish_text`] puts the dictated text there alone, marked with the types of
//! nspasteboard.org that keep it out of clipboard managers' history (transient, concealed,
//! auto-generated). [`Session::wait_and_restore`] puts the snapshot back once the target has had
//! time to read the text, unless the person copied something new meanwhile (the pasteboard's
//! change count moved on); [`Session::keep`] leaves the text on the pasteboard instead.
//!
//! macOS gives no read receipt for plain data, so the wait is a fixed time after the chord
//! ([`READ_WAIT`]), long enough for the slow readers measured (Electron apps, Office), and short
//! enough that a copy right after a dictation is not overwritten.

use std::thread;
use std::time::Duration;

use objc2::rc::{Retained, autoreleasepool};
use objc2::runtime::{AnyClass, AnyObject};
use objc2::{class, msg_send};
use objc2_foundation::NSString;

/// How long after the paste chord the person's clipboard comes back.
pub const READ_WAIT: Duration = Duration::from_millis(600);
/// The same when the chord could not be sent.
pub const NO_CHORD_WAIT: Duration = Duration::from_millis(150);
/// A single item's type bigger than this is not kept.
const MAX_TYPE_BYTES: usize = 64 * 1024 * 1024;

/// The plain-text type (`NSPasteboardTypeString`).
const TEXT: &str = "public.utf8-plain-text";
/// The markers of nspasteboard.org that clipboard managers honour.
const MARKERS: [&str; 3] = [
    "org.nspasteboard.TransientType",
    "org.nspasteboard.ConcealedType",
    "org.nspasteboard.AutoGeneratedType",
];

/// One saved pasteboard item: each of its types with its data.
type Item = Vec<(String, Vec<u8>)>;

fn general() -> Retained<AnyObject> {
    let class: &AnyClass = class!(NSPasteboard);
    // SAFETY: the general pasteboard always exists.
    unsafe { msg_send![class, generalPasteboard] }
}

/// The plain text on the general pasteboard, if it holds any. The page's paste buttons read it
/// through the shell: WKWebView does not let a page read the clipboard by itself.
pub fn text() -> Option<String> {
    autoreleasepool(|_| {
        let pasteboard = general();
        let kind = NSString::from_str(TEXT);
        // SAFETY: an NSPasteboard method with an NSString type; it answers nil without text.
        let value: Option<Retained<NSString>> =
            unsafe { msg_send![&*pasteboard, stringForType: &*kind] };
        value.map(|value| value.to_string())
    })
}

/// Puts the file at `path` on the general pasteboard as a file (its file URL), as Finder's copy does: a paste in
/// Finder, a chat or any program that takes files gets the file itself.
pub fn copy_file(path: &str) -> Result<(), String> {
    autoreleasepool(|_| {
        let pasteboard = general();
        let path = NSString::from_str(path);
        let url_class: &AnyClass = class!(NSURL);
        // SAFETY: NSURL's class constructor with an NSString path; it answers nil for no path.
        let url: Option<Retained<AnyObject>> = unsafe { msg_send![url_class, fileURLWithPath: &*path] };
        let url = url.ok_or_else(|| "no file to copy".to_owned())?;
        let array_class: &AnyClass = class!(NSArray);
        // SAFETY: NSArray's class constructor with one object.
        let list: Retained<AnyObject> = unsafe { msg_send![array_class, arrayWithObject: &*url] };
        // SAFETY: NSPasteboard's clearContents and writeObjects: with an array of NSURLs.
        let _: isize = unsafe { msg_send![&*pasteboard, clearContents] };
        let written: bool = unsafe { msg_send![&*pasteboard, writeObjects: &*list] };
        if written { Ok(()) } else { Err("the pasteboard refused the file".to_owned()) }
    })
}

/// The general pasteboard's change count now: it goes up with every write to it, even one of
/// what it held already, so a count that stays is a copy that brought nothing.
pub fn current_change_count() -> isize {
    autoreleasepool(|_| change_count(&general()))
}

fn change_count(pasteboard: &AnyObject) -> isize {
    // SAFETY: an NSPasteboard property.
    unsafe { msg_send![pasteboard, changeCount] }
}

fn bytes_of(data: &AnyObject) -> Vec<u8> {
    // SAFETY: NSData's length and bytes, which stay valid while `data` does.
    unsafe {
        let length: usize = msg_send![data, length];
        if length == 0 {
            return Vec::new();
        }
        let bytes: *const u8 = msg_send![data, bytes];
        std::slice::from_raw_parts(bytes, length).to_vec()
    }
}

fn data_from(bytes: &[u8]) -> Retained<AnyObject> {
    let class: &AnyClass = class!(NSData);
    // SAFETY: NSData copies the bytes it is given.
    unsafe {
        msg_send![
            class,
            dataWithBytes: bytes.as_ptr().cast::<std::ffi::c_void>(),
            length: bytes.len()
        ]
    }
}

fn snapshot(pasteboard: &AnyObject) -> Vec<Item> {
    let mut items = Vec::new();
    // SAFETY: NSPasteboard's items and NSPasteboardItem's types and data; each may be nil.
    unsafe {
        let list: Option<Retained<AnyObject>> = msg_send![pasteboard, pasteboardItems];
        let Some(list) = list else {
            return items;
        };
        let count: usize = msg_send![&*list, count];
        for index in 0..count {
            let item: Retained<AnyObject> = msg_send![&*list, objectAtIndex: index];
            let types: Option<Retained<AnyObject>> = msg_send![&*item, types];
            let Some(types) = types else { continue };
            let type_count: usize = msg_send![&*types, count];
            let mut saved = Vec::new();
            for type_index in 0..type_count {
                let kind: Retained<NSString> = msg_send![&*types, objectAtIndex: type_index];
                let data: Option<Retained<AnyObject>> = msg_send![&*item, dataForType: &*kind];
                let Some(data) = data else { continue };
                let length: usize = msg_send![&*data, length];
                if length > MAX_TYPE_BYTES {
                    continue;
                }
                saved.push((kind.to_string(), bytes_of(&data)));
            }
            if !saved.is_empty() {
                items.push(saved);
            }
        }
    }
    items
}

fn new_item() -> Retained<AnyObject> {
    let class: &AnyClass = class!(NSPasteboardItem);
    // SAFETY: a plain allocation and initialisation.
    unsafe { msg_send![class, new] }
}

fn set_data(item: &AnyObject, kind: &str, bytes: &[u8]) -> bool {
    let kind = NSString::from_str(kind);
    let data = data_from(bytes);
    // SAFETY: an NSPasteboardItem, an NSString type and an NSData.
    unsafe { msg_send![item, setData: &*data, forType: &*kind] }
}

fn write_items(pasteboard: &AnyObject, items: &[Retained<AnyObject>]) -> bool {
    let class: &AnyClass = class!(NSMutableArray);
    // SAFETY: an array of NSPasteboardItems, written after the pasteboard was cleared.
    unsafe {
        let array: Retained<AnyObject> = msg_send![class, array];
        for item in items {
            let () = msg_send![&*array, addObject: &**item];
        }
        let _: isize = msg_send![pasteboard, clearContents];
        msg_send![pasteboard, writeObjects: &*array]
    }
}

/// One paste's use of the pasteboard.
pub struct Session {
    saved: Vec<Item>,
    /// The change count once the text was published: if it moved on, the person copied something.
    published: Option<isize>,
}

impl Session {
    /// Snapshots the pasteboard.
    pub fn begin() -> Result<Self, String> {
        autoreleasepool(|_| {
            let pasteboard = general();
            Ok(Self {
                saved: snapshot(&pasteboard),
                published: None,
            })
        })
    }

    /// Puts `text` on the pasteboard alone, with the markers.
    pub fn publish_text(&mut self, text: &str) -> Result<(), String> {
        autoreleasepool(|_| {
            let pasteboard = general();
            let item = new_item();
            if !set_data(&item, TEXT, text.as_bytes()) {
                return Err("the pasteboard item did not take the text".to_owned());
            }
            for marker in MARKERS {
                set_data(&item, marker, &[]);
            }
            if !write_items(&pasteboard, &[item]) {
                return Err("the pasteboard did not take the text".to_owned());
            }
            self.published = Some(change_count(&pasteboard));
            Ok(())
        })
    }

    /// Waits for the target to read the text, then puts the person's clipboard back unless they
    /// copied something new meanwhile.
    pub fn wait_and_restore(self, chord_sent: bool) {
        thread::sleep(if chord_sent { READ_WAIT } else { NO_CHORD_WAIT });
        autoreleasepool(|_| {
            let pasteboard = general();
            if self.published != Some(change_count(&pasteboard)) {
                log::info!("paste: the clipboard changed meanwhile; it is left as it is");
                return;
            }
            self.put_back(&pasteboard);
        });
    }

    /// Puts the person's clipboard back at once, whatever is on it now: after a copy of the
    /// selection, which wrote the program's copy there.
    pub fn restore(self) {
        autoreleasepool(|_| self.put_back(&general()));
    }

    fn put_back(&self, pasteboard: &AnyObject) {
        if self.saved.is_empty() {
            // SAFETY: an NSPasteboard method.
            let _: isize = unsafe { msg_send![pasteboard, clearContents] };
            return;
        }
        let items: Vec<Retained<AnyObject>> = self
            .saved
            .iter()
            .map(|saved| {
                let item = new_item();
                for (kind, bytes) in saved {
                    set_data(&item, kind, bytes);
                }
                item
            })
            .collect();
        if !write_items(pasteboard, &items) {
            log::warn!("paste: the clipboard could not be put back");
        }
    }

    /// Leaves the text on the pasteboard for the person to paste by hand.
    pub fn keep(self) {}
}

#[cfg(test)]
mod tests {
    use super::*;

    fn text_on_pasteboard() -> Option<String> {
        autoreleasepool(|_| {
            let pasteboard = general();
            let kind = NSString::from_str(TEXT);
            // SAFETY: an NSPasteboard method that returns nil when there is no text.
            let text: Option<Retained<NSString>> =
                unsafe { msg_send![&*pasteboard, stringForType: &*kind] };
            text.map(|text| text.to_string())
        })
    }

    /// Uses the real pasteboard, so it is run only on request
    /// (`cargo test -- --ignored pasteboard`).
    #[test]
    #[ignore = "uses the person's real clipboard"]
    fn the_clipboard_comes_back_after_a_paste_and_the_text_stays_for_a_copy_only() {
        let before = text_on_pasteboard();
        let mut session = Session::begin().unwrap();
        session.publish_text("拉斐爾 dictation").unwrap();
        assert_eq!(text_on_pasteboard().as_deref(), Some("拉斐爾 dictation"));
        session.wait_and_restore(false);
        assert_eq!(text_on_pasteboard(), before);

        let mut session = Session::begin().unwrap();
        session.publish_text("kept").unwrap();
        session.keep();
        assert_eq!(text_on_pasteboard().as_deref(), Some("kept"));
    }
}
